def extra_blocks(article_id):
    first_title, first_text, second_title, second_text, checklist = DETAILS[article_id]
    return [
        {'type': 'HEADING', 'level': 2, 'text': first_title},
        {'type': 'PARAGRAPH', 'text': first_text},
        {'type': 'HEADING', 'level': 2, 'text': second_title},
        {'type': 'PARAGRAPH', 'text': second_text},
        {'type': 'HEADING', 'level': 2, 'text': 'Что подготовить для обсуждения'},
        {'type': 'BULLET_LIST', 'items': checklist},
        {'type': 'PARAGRAPH', 'text': 'Если рассматриваете разработку или доработку, расскажите ITWEBS о своей ситуации и укажите ссылки на доступные материалы. Обсуждение начнём с задачи и необходимого состава работ.'},
    ]
